(()=>{let design='1';try{design=localStorage.getItem('vibe-entrance-design')||'1';}catch{}const dq=new URLSearchParams(location.search).get('design');if(['1','2','3'].includes(dq))design=dq;function setDesign(d){document.body.dataset.design=d;document.querySelectorAll('[data-design]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.design===d)));try{localStorage.setItem('vibe-entrance-design',d);}catch{}}setDesign(['1','2','3'].includes(design)?design:'1');const tabs=[...document.querySelectorAll('[role=tab]')];tabs.forEach((b,i)=>{b.onclick=()=>setDesign(b.dataset.design);b.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const next=tabs[(i+(e.key==='ArrowRight'?1:2))%3];next.click();next.focus();}};});document.querySelector('#motion-toggle').onclick=e=>{const paused=document.body.classList.toggle('motion-paused');e.currentTarget.setAttribute('aria-pressed',String(paused));e.currentTarget.textContent=paused?'Resume motion':'Pause motion';};let edition='one';try{edition=localStorage.getItem('vibe-edition')==='law'?'law':'one';}catch{}function links(){document.querySelectorAll('[data-workspace]').forEach(a=>{a.href='/account/?edition='+edition+'#'+a.dataset.workspace;});document.querySelectorAll('[data-plans]').forEach(a=>a.href='/plans/?edition='+edition);}links();document.querySelectorAll('[data-select]').forEach(a=>a.addEventListener('click',()=>{try{localStorage.setItem('vibe-edition',a.dataset.select);}catch{}}));let saved=false;try{saved=!!localStorage.getItem('vibe-edition');}catch{}if(saved){const name=edition==='law'?'Vibe Law':'Vibe One';document.querySelector('#resume').hidden=false;document.querySelector('#resume-link').href='/index.html?edition='+edition;document.querySelector('#resume-link').textContent='Return to '+name+' →';document.querySelector('#current-space').textContent='Last space: '+name;}if(location.hash&&!['#overview','#top'].includes(location.hash))location.replace('/account/?edition='+edition+location.hash);const seek=new URLSearchParams(location.search).get('t');if(seek!==null&&Number.isFinite(Number(seek))){document.querySelectorAll('.balance-beam,.balance-pan').forEach(el=>{el.style.animationDelay=-Number(seek)+'s';el.style.animationPlayState='paused';});}window.__ready=true;})();